app.get('/api/navigation/bootstrap',(q,r)=>{const code=String(q.query.airport||'SKY').toUpperCase(),airport=db.prepare('SELECT id,iata code,name,city,country FROM airports WHERE iata=?').get(code);if(!airport)return r.status(404).json({error:'Airport navigation data unavailable'});const nodes=navigation.nodes(code),edges=db.prepare(`SELECT e.* FROM navigation_edges e JOIN navigation_nodes n ON n.id=e.from_node JOIN navigation_floors f ON f.id=n.floor_id JOIN navigation_terminals t ON t.id=f.terminal_id WHERE t.airport_id=? AND e.active=1`).all((airport as any).id),u=identity(q);let journey:any=null;if(u){journey=db.prepare(`SELECT b.id bookingId,b.pnr,f.id flightId,f.number,f.origin,f.destination,f.departure,f.arrival,f.terminal,f.gate,f.status FROM bookings b JOIN flights f ON f.id=b.flight_id WHERE b.user_email=? AND b.status='CONFIRMED' ORDER BY b.id DESC LIMIT 1`).get(u.email);if(journey){journey.gateNumber=normalizedGate(journey.terminal,journey.gate);journey.gateNode=nodes.find((n:any)=>n.gate_number===journey.gateNumber)||null;if(journey.gateNode){try{const entrance=nodes.find((n:any)=>n.node_key==='t2_entrance_a')||nodes.find((n:any)=>n.type==='ENTRANCE'),route=entrance?navigation.findRoute(entrance.id,journey.gateNode.id,'FASTEST'):null,exists=(db.prepare("SELECT count(*) c FROM notifications WHERE recipient=? AND category='NAVIGATION' AND message LIKE ?").get(u.email,`%${journey.number}%${journey.gateNumber}%`)as any).c;if(route&&!exists)db.prepare("INSERT INTO notifications(recipient,category,message,created_at) VALUES(?,'NAVIGATION',?,?)").run(u.email,`Your flight ${journey.number} uses Gate ${journey.gateNumber}. From the demo terminal entrance, the graph route is approximately ${route.walkingTime} minutes (${route.distance} m).`,now())}catch{}}}}r.json({airport:{...airport,demo:true,label:'SEEDED DEMO AIRPORT DATA'},terminals:db.prepare('SELECT id,name,active FROM navigation_terminals WHERE airport_id=?').all((airport as any).id),nodes,edges,journey,defaults:{currentLocation:'t2_entrance_a',walkingSpeed:1.35,securityStatus:'NOT_STARTED'},capabilities:{indoorPositioning:false,browserGeolocation:'OUTDOOR_ONLY',modes:['2D','3D'],routeTypes:['FASTEST','SHORTEST','ACCESSIBLE','LOW_WALKING','FAMILY']}})});
app.get('/api/navigation/search',(q,r)=>{const term=String(q.query.q||'').trim(),rows:any[]=term?navigation.search(term,String(q.query.airport||'SKY')):navigation.nodes(String(q.query.airport||'SKY')).slice(0,20),from=q.query.from;if(from)for(const x of rows)try{const route=navigation.findRoute(String(from),x.id,'SHORTEST');x.distance=route.distance;x.walkingTime=route.walkingTime}catch{}r.json(rows)});
app.post('/api/navigation/route',(q,r)=>{try{const{start,destination,mode='FASTEST'}=q.body||{};if(!['FASTEST','SHORTEST','ACCESSIBLE','LOW_WALKING','FAMILY'].includes(mode))return r.status(400).json({error:'Invalid route mode'});const selected=navigation.findRoute(start,destination,mode as RouteMode),options=navigation.options(start,destination);r.json({selected,options})}catch(e:any){r.status(422).json({error:e.message})}});
app.get('/api/navigation/nearby',(q,r)=>{const categories=String(q.query.categories||'').split(',').filter(Boolean);r.json(navigation.nearby(Number(q.query.nodeId),categories,Number(q.query.limit||10)))});
app.post('/api/navigation/sessions',(q,r)=>{const u=identity(q);if(!u)return r.status(401).json({error:'Authentication required'});try{const route=navigation.findRoute(q.body.start,q.body.destination,q.body.mode||'FASTEST'),id=Number(db.prepare("INSERT INTO navigation_sessions(user_id,airport_code,start_node,destination_node,route_mode,status,progress,created_at,updated_at) VALUES(?,'SKY',?,?,?,'NAVIGATING',0,?,?)").run(u.id,route.nodes[0].id,route.nodes.at(-1)!.id,route.mode,now(),now()).lastInsertRowid);r.json({sessionId:id,status:'NAVIGATING',route})}catch(e:any){r.status(422).json({error:e.message})}});
