app.post('/api/admin/navigation/nodes',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;const b=q.body||{};if(!b.nodeKey||!b.floorId||!b.name||!b.type)return r.status(400).json({error:'Node key, floor, name and type are required'});try{const id=Number(db.prepare('INSERT INTO navigation_nodes(node_key,floor_id,name,type,x,y,z,accessible,wide_route,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)').run(b.nodeKey,b.floorId,b.name,b.type,Number(b.x||0),Number(b.y||0),Number(b.z||0),b.accessible===false?0:1,b.wideRoute===false?0:1,now()).lastInsertRowid);navigation.invalidate();db.prepare("INSERT INTO navigation_audit_logs(admin_id,action,entity_type,entity_id,detail,created_at) VALUES(?,'CREATED','NODE',?,?,?)").run(u.id,id,JSON.stringify(b),now());r.json(navigation.node(id))}catch(e:any){r.status(409).json({error:e.message})}});
