app.post('/api/profile/change-password',(q,r)=>{const u=profileUser(q,r);if(!u)return;const row:any=db.prepare('SELECT password_hash FROM users WHERE id=?').get(u.id),[salt,key]=row.password_hash.split(':');if(!timingSafeEqual(Buffer.from(key,'hex'),scryptSync(String(q.body.currentPassword||''),salt,64)))return r.status(403).json({error:'Current password is incorrect'});if(String(q.body.newPassword||'').length<10)return r.status(422).json({error:'New password must be at least 10 characters'});db.transaction(()=>{db.prepare('UPDATE users SET password_hash=?,must_change_password=0 WHERE id=?').run(hash(q.body.newPassword),u.id);db.prepare('DELETE FROM sessions WHERE user_id=?').run(u.id);db.prepare("INSERT INTO security_events(user_id,event_type,metadata,created_at) VALUES(?,'PASSWORD_CHANGED','{}',?)").run(u.id,now())})();r.json({ok:true,reauthenticate:true})});
app.get('/api/profile/sessions',(q,r)=>{const u=profileUser(q,r);if(!u)return;r.json(db.prepare('SELECT id,created_at,expires_at FROM sessions WHERE user_id=? ORDER BY created_at DESC').all(u.id))});
