app.post('/api/journeys/:id/checkin',(q,r)=>{const u=journeyUser(q,r);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirm passenger details to check in.'});try{r.json(journeyService.checkin(u,Number(q.params.id)))}catch(e:any){r.status(e.status||422).json({error:e.message})}});
