app.post('/api/journeys/:id/change-seat',(q,r)=>{const u=journeyUser(q,r);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Seat change confirmation required'});const j:any=journeyService.getById(u,Number(q.params.id));if(!j)return r.status(404).json({error:'Journey not found'});const b=j.booking,newSeat=String(q.body.seat||'').toUpperCase(),passenger=j.passengers.find((p:any)=>p.id===Number(q.body.passengerId))||j.passengers[0];if(!passenger)return r.status(422).json({error:'Journey passenger not found'});try{db.transaction(()=>{const seat:any=db.prepare('SELECT * FROM seats WHERE flight_id=? AND label=?').get(b.flight_id,newSeat);if(!seat||!['AVAILABLE','PREMIUM'].includes(seat.status))throw Error('Seat is not available');const claim=db.prepare("UPDATE seats SET status='OCCUPIED' WHERE id=? AND status IN ('AVAILABLE','PREMIUM')").run(seat.id);if(claim.changes!==1)throw Error('Seat allocation conflict');const oldSeat=passenger.seat;db.prepare("UPDATE seats SET status='AVAILABLE' WHERE flight_id=? AND label=? AND status='OCCUPIED'").run(b.flight_id,oldSeat);db.prepare("UPDATE booking_seats SET status='RELEASED',updated_at=? WHERE booking_id=? AND seat_label=? AND status='ACTIVE'").run(now(),b.id,oldSeat);db.prepare("INSERT INTO booking_seats(booking_id,flight_id,seat_label,status,created_at,updated_at) VALUES(?,?,?,'ACTIVE',?,?)").run(b.id,b.flight_id,newSeat,now(),now());db.prepare('UPDATE journey_passengers SET seat=? WHERE id=?').run(newSeat,passenger.id);const seats=(db.prepare('SELECT seat FROM journey_passengers WHERE journey_id=? ORDER BY id').all(j.id)as any[]).map(x=>x.seat).join(',');db.prepare('UPDATE bookings SET seat=? WHERE id=?').run(seats,b.id);journeyService.event(j.id,'SEAT_CHANGED',{passengerId:passenger.id,from:oldSeat,to:newSeat})})();r.json(journeyService.getById(u,j.id))}catch(e:any){r.status(409).json({error:e.message})}});
app.post('/api/journeys/:id/baggage',(q,r)=>{const u=journeyUser(q,r);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirm baggage purchase'});const j:any=journeyService.getById(u,Number(q.params.id));if(!j)return r.status(404).json({error:'Journey not found'});const weight=Number(q.body.weightKg),price=weight===10?1200:weight===20?2100:0;if(!price)return r.status(422).json({error:'Available demo options are 10 kg or 20 kg'});const tx=db.transaction(()=>{const id=Number(db.prepare("INSERT INTO journey_baggage(journey_id,passenger_id,kind,weight_kg,pieces,status,price,created_at) VALUES(?,?,'EXTRA_CHECKED',?,1,'PURCHASED',?,?)").run(j.id,j.passengers[0]?.id,weight,price,now()).lastInsertRowid);db.prepare('UPDATE bookings SET total=total+? WHERE id=?').run(price,j.booking_id);db.prepare('UPDATE payments SET amount=amount+? WHERE booking_id=?').run(price,j.booking_id);journeyService.event(j.id,'BAGGAGE_UPDATED',{weightKg:weight,price});return id})();r.json({id:tx,weightKg:weight,price,status:'PURCHASED'})});
app.post('/api/journeys/:id/share',(q,r)=>{const u=journeyUser(q,r);if(!u)return;const j:any=journeyService.getById(u,Number(q.params.id));if(!j)return r.status(404).json({error:'Journey not found'});const fields=Array.isArray(q.body.fields)?q.body.fields.filter((x:string)=>['flight','route','departure','status'].includes(x)):['flight','route','departure','status'],token=randomBytes(12).toString('hex');db.prepare('INSERT INTO journey_shares(journey_id,token,fields,expires_at,created_at) VALUES(?,?,?,?,?)').run(j.id,token,JSON.stringify(fields),new Date(Date.now()+7*86400000).toISOString(),now());r.json({url:`/shared-journey/${token}`,fields,expiresIn:'7 days'})});
app.get('/api/admin/journeys/analytics',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;const base:any=journeyService.analytics(),checkin=(db.prepare("SELECT count(*) c FROM journey_passengers WHERE checkin_status='CHECKED_IN'").get()as any).c,totalP=(db.prepare('SELECT count(*) c FROM journey_passengers').get()as any).c,nav=(db.prepare('SELECT count(*) c FROM navigation_sessions').get()as any).c,offer=(db.prepare("SELECT count(*) c FROM offer_redemptions WHERE status='SUCCESS'").get()as any).c,wl=(db.prepare("SELECT count(*) c FROM waitlist_entries WHERE status='CONFIRMED'").get()as any).c;r.json({...base,checkinRate:totalP?Math.round(checkin/totalP*100):0,navigationLaunches:nav,offerConversions:offer,waitlistConversions:wl})});
app.post('/api/admin/journeys/booking/:bookingId/payment',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});const status=String(q.body.status||'');if(!['PENDING','FAILED','SUCCESS','REFUNDED'].includes(status))return r.status(422).json({error:'Invalid payment status'});const b:any=db.prepare('SELECT * FROM bookings WHERE id=?').get(q.params.bookingId);if(!b)return r.status(404).json({error:'Booking not found'});db.transaction(()=>{db.prepare('UPDATE bookings SET payment_status=? WHERE id=?').run(status,b.id);db.prepare('UPDATE payments SET status=? WHERE booking_id=?').run(status,b.id);const j:any=db.prepare('SELECT id FROM journeys WHERE booking_id=?').get(b.id);if(j){journeyService.event(j.id,status==='FAILED'?'PAYMENT_FAILED':status==='PENDING'?'PAYMENT_REQUIRED':'PAYMENT_COMPLETED',{adminId:u.id});journeyService.syncJourney(j.id)}})();r.json({bookingId:b.id,status})});
app.post('/api/admin/journeys/flight/:flightId/state',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});const allowed=['ON_TIME','DELAYED','BOARDING','DEPARTED','ARRIVED','CANCELLED','DIVERTED'];if(!allowed.includes(q.body.status))return r.status(422).json({error:'Invalid flight state'});db.prepare('UPDATE flights SET status=? WHERE id=?').run(q.body.status,q.params.flightId);let affected=0;if(q.body.status==='CANCELLED'){const bs=db.prepare("SELECT id,user_email FROM bookings WHERE flight_id=? AND status='CONFIRMED'").all(q.params.flightId)as any[];for(const b of bs){try{cancelAndRecover(b.id);affected++;db.prepare("INSERT INTO notifications(recipient,category,message,created_at) VALUES(?,'FLIGHT',?,?)").run(b.user_email,'Your flight was cancelled. The booking was cancelled and refund processing was initiated.',now())}catch{}}smartWaitlist.expireFlightEntries()}const js=db.prepare('SELECT journey_id FROM journey_segments WHERE flight_id=?').all(q.params.flightId)as any[];for(const x of js)journeyService.syncJourney(x.journey_id);r.json({status:q.body.status,journeysUpdated:js.length,affectedBookings:affected})});
app.post('/api/demo/journeys/multi-passenger',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});try{const out=db.transaction(()=>{const user:any=db.prepare("SELECT * FROM users WHERE email='passengerx@demo.com'").get(),f:any=db.prepare("SELECT * FROM flights WHERE number='SK218'").get(),seats=db.prepare("SELECT * FROM seats WHERE flight_id=? AND status IN ('AVAILABLE','PREMIUM') ORDER BY label LIMIT 2").all(f.id)as any[];if(seats.length<2)throw Error('Two seats unavailable');for(const s of seats)db.prepare("UPDATE seats SET status='OCCUPIED' WHERE id=?").run(s.id);const code=`MULTI${Date.now().toString().slice(-4)}`,bid=Number(db.prepare("INSERT INTO bookings(pnr,user_name,user_email,flight_id,seat,fare_tier,total,status,payment_status,created_at,original_fare,discount_amount) VALUES(?,'Passenger X',?,?,?,'Standard',12000,'CONFIRMED','SUCCESS',?,12000,0)").run(code,user.email,f.id,seats.map(s=>s.label).join(','),now()).lastInsertRowid);for(const s of seats)db.prepare("INSERT INTO booking_seats(booking_id,flight_id,seat_label,status,created_at,updated_at) VALUES(?,?,?,'ACTIVE',?,?)").run(bid,f.id,s.label,now(),now());db.prepare("INSERT INTO payments(booking_id,amount,method,status,transaction_id,created_at) VALUES(?,12000,'DEMO','SUCCESS',?,?)").run(bid,`TXN-${code}`,now());db.prepare("INSERT INTO tickets(booking_id,ticket_no,created_at) VALUES(?,?,?)").run(bid,`SK-${code}`,now());const journeys=journeyService.syncUser(user),j=journeys.find((x:any)=>x.booking_id===bid);return j})();r.json(out)}catch(e:any){r.status(409).json({error:e.message})}});
app.post('/api/demo/journeys/multi-segment',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});try{const out=db.transaction(()=>{const passenger:any=db.prepare("SELECT * FROM users WHERE email='passengerx@demo.com'").get(),f1:any=db.prepare("SELECT * FROM flights WHERE number='SK880'").get();let f2:any=db.prepare("SELECT * FROM flights WHERE number='DX204'").get();if(!f2){const id=Number(db.prepare("INSERT INTO flights(number,airline,origin,destination,departure,arrival,terminal,gate,status,capacity,fare,baggage) VALUES('DX204','SkyBook Connect','DXB','LHR','2026-08-23T02:25','2026-08-23T06:30','T1','A20','SCHEDULED',6,22000,25)").run().lastInsertRowid);for(const label of ['14A','14B','14C','14D','14E','14F'])db.prepare("INSERT INTO seats(flight_id,label,status,price) VALUES(?,?,'AVAILABLE',500)").run(id,label);f2=db.prepare('SELECT * FROM flights WHERE id=?').get(id)}let b:any=db.prepare("SELECT * FROM bookings WHERE user_email=? AND flight_id=? AND status='CONFIRMED'").get(passenger.email,f1.id);if(!b){const seat:any=db.prepare("SELECT * FROM seats WHERE flight_id=? AND status='AVAILABLE' ORDER BY label LIMIT 1").get(f1.id);db.prepare("UPDATE seats SET status='OCCUPIED' WHERE id=?").run(seat.id);const bid=Number(db.prepare("INSERT INTO bookings(pnr,user_name,user_email,flight_id,seat,fare_tier,total,status,payment_status,created_at,original_fare,discount_amount) VALUES('MULTI01','Passenger X',?,?,?,'Standard',19356,'CONFIRMED','SUCCESS',?,19356,0)").run(passenger.email,f1.id,seat.label,now()).lastInsertRowid);db.prepare("INSERT INTO booking_seats(booking_id,flight_id,seat_label,status,created_at,updated_at) VALUES(?,?,?,'ACTIVE',?,?)").run(bid,f1.id,seat.label,now(),now());db.prepare("INSERT INTO payments(booking_id,amount,method,status,transaction_id,created_at) VALUES(?,19356,'DEMO','SUCCESS',?,?)").run(bid,`TXN-MULTI-${Date.now()}`,now());db.prepare("INSERT INTO tickets(booking_id,ticket_no,created_at) VALUES(?,'SK-MULTI',?)").run(bid,now());b=db.prepare('SELECT * FROM bookings WHERE id=?').get(bid)}journeyService.syncUser(passenger);const j:any=db.prepare('SELECT * FROM journeys WHERE booking_id=?').get(b.id),exists=db.prepare('SELECT 1 FROM journey_segments WHERE journey_id=? AND segment_order=2').get(j.id);if(!exists)db.prepare("INSERT INTO journey_segments(journey_id,flight_id,segment_order,origin,destination,departure,arrival,terminal,gate,status,created_at,updated_at) VALUES(?,?,2,'DXB','LHR',?,?,?,?,?,?,?)").run(j.id,f2.id,f2.departure,f2.arrival,f2.terminal,f2.gate,f2.status,now(),now());journeyService.event(j.id,'LAYOVER_PLANNED',{airport:'DXB',minutes:135});return journeyService.getById(passenger,j.id)})();r.json(out)}catch(e:any){r.status(409).json({error:e.message})}});
app.post('/api/admin/journeys/:id/complete',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});const j:any=db.prepare('SELECT * FROM journeys WHERE id=?').get(q.params.id);if(!j)return r.status(404).json({error:'Journey not found'});db.prepare("UPDATE bookings SET status='COMPLETED' WHERE id=?").run(j.booking_id);journeyService.event(j.id,'COMPLETED',{adminId:u.id});r.json(journeyService.syncJourney(j.id))});
app.post('/api/admin/journeys/flight/:flightId/checkin-open',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});db.prepare('INSERT INTO journey_demo_controls(flight_id,checkin_open,updated_at) VALUES(?,1,?) ON CONFLICT(flight_id) DO UPDATE SET checkin_open=1,updated_at=excluded.updated_at').run(q.params.flightId,now());r.json({checkinOpen:true})});
