app.post('/api/offers/save',(q,r)=>{const u=identity(q);if(!u)return r.status(401).json({error:'Authentication required'});const o=offers.get(Number(q.body.offerId));if(!o)return r.status(404).json({error:'Offer not found'});db.prepare('INSERT OR IGNORE INTO saved_offers(user_id,offer_id,saved_at) VALUES(?,?,?)').run(u.id,o.id,now());db.prepare("INSERT OR IGNORE INTO offer_notifications(user_id,offer_id,type,message) VALUES(?,?,'SAVED_EXPIRY',?)").run(u.id,o.id,`Saved ${o.promo_code}; expiry reminders enabled.`);db.prepare("INSERT INTO notifications(recipient,category,message,created_at) VALUES(?,'SYSTEM',?,?)").run(u.email,`Offer ${o.promo_code} saved. It expires ${new Date(o.expires_at).toLocaleDateString('en-IN')}.`,now());r.json({saved:true})});
app.delete('/api/offers/save/:id',(q,r)=>{const u=identity(q);if(!u)return r.status(401).json({error:'Authentication required'});db.prepare('DELETE FROM saved_offers WHERE user_id=? AND offer_id=?').run(u.id,q.params.id);r.json({saved:false})});
function validateOfferInput(b:any,partial=false){const errors:string[]=[];if(!partial&&(!b.title||!b.promoCode||!b.discountType||b.discountValue==null))errors.push('Title, promo code, discount type and value are required.');if(b.promoCode!==undefined&&!/^[A-Z0-9-]{4,30}$/.test(String(b.promoCode).toUpperCase()))errors.push('Promo code must be 4–30 letters, numbers or hyphens.');if(b.discountType!==undefined&&!['PERCENTAGE','FIXED_AMOUNT','UP_TO_AMOUNT'].includes(b.discountType))errors.push('Invalid discount type.');if(b.discountValue!==undefined&&(Number(b.discountValue)<=0||(b.discountType==='PERCENTAGE'||b.discountType==='UP_TO_AMOUNT')&&Number(b.discountValue)>100))errors.push('Discount value must be positive and percentage discounts cannot exceed 100%.');if(b.maximumDiscount!==undefined&&Number(b.maximumDiscount)<0)errors.push('Maximum discount cannot be negative.');if(b.minimumFare!==undefined&&Number(b.minimumFare)<0)errors.push('Minimum fare cannot be negative.');if(b.startAt&&b.expiresAt&&Date.parse(b.startAt)>=Date.parse(b.expiresAt))errors.push('Offer expiry must be after its start.');if(b.usageLimit!==undefined&&b.usageLimit!==null&&Number(b.usageLimit)<1)errors.push('Usage limit must be at least 1.');if(b.perUserLimit!==undefined&&Number(b.perUserLimit)<1)errors.push('Per-user limit must be at least 1.');for(const x of b.routes||[])if(x.origin!=='*'&&!db.prepare('SELECT 1 FROM airports WHERE iata=?').get(x.origin)||x.destination!=='*'&&!db.prepare('SELECT 1 FROM airports WHERE iata=?').get(x.destination))errors.push(`Unknown route ${x.origin} → ${x.destination}.`);return errors}
function syncOfferRelations(id:number,body:any){if(body.routes){db.prepare('DELETE FROM offer_routes WHERE offer_id=?').run(id);for(const x of body.routes)db.prepare('INSERT INTO offer_routes(offer_id,origin,destination) VALUES(?,?,?)').run(id,x.origin,x.destination)}if(body.airlines){db.prepare('DELETE FROM offer_airlines WHERE offer_id=?').run(id);for(const x of body.airlines)db.prepare('INSERT INTO offer_airlines(offer_id,airline) VALUES(?,?)').run(id,x)}if(body.cabins){db.prepare('DELETE FROM offer_cabins WHERE offer_id=?').run(id);for(const x of body.cabins)db.prepare('INSERT INTO offer_cabins(offer_id,cabin) VALUES(?,?)').run(id,x)}}
app.post('/api/admin/offers',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;const b=q.body||{},validationErrors=validateOfferInput(b);if(validationErrors.length)return r.status(400).json({error:validationErrors.join(' ')});try{const id=Number(db.transaction(()=>{const id=Number(db.prepare(`INSERT INTO offers(title,description,category,discount_type,discount_value,maximum_discount,minimum_fare,promo_code,start_at,expires_at,booking_start_at,booking_end_at,travel_start_at,travel_end_at,status,usage_limit,per_user_limit,eligibility,weekend_only,terms,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(b.title,b.description||'',b.category||'SEASONAL',b.discountType,b.discountValue,b.maximumDiscount??null,b.minimumFare||0,String(b.promoCode).toUpperCase(),b.startAt,b.expiresAt,b.bookingStartAt||b.startAt,b.bookingEndAt||b.expiresAt,b.travelStartAt||b.startAt,b.travelEndAt||b.expiresAt,b.status||'DISABLED',b.usageLimit??null,b.perUserLimit||1,b.eligibility||'ALL',b.weekendOnly?1:0,b.terms||'',u.id,now(),now()).lastInsertRowid);db.prepare('INSERT INTO promo_codes(offer_id,code,active) VALUES(?,?,?)').run(id,String(b.promoCode).toUpperCase(),b.status==='ACTIVE'?1:0);syncOfferRelations(id,b);db.prepare("INSERT INTO offer_audit_logs(offer_id,admin_id,action,changed_fields,created_at) VALUES(?,?,'CREATED',?,?)").run(id,u.id,JSON.stringify(b),now());return id})());r.json(offers.get(id))}catch(e:any){r.status(409).json({error:e.message.includes('UNIQUE')?'Promo code already exists.':e.message})}});
app.put('/api/admin/offers/:id',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;const id=Number(q.params.id),existing=offers.get(id);if(!existing)return r.status(404).json({error:'Offer not found'});const redeemed=(db.prepare("SELECT count(*) c FROM offer_redemptions WHERE offer_id=? AND status='SUCCESS'").get(id)as any).c,b=q.body||{},validationErrors=validateOfferInput(b,true);if(validationErrors.length)return r.status(400).json({error:validationErrors.join(' ')});if(redeemed&&(['discountType','discountValue','promoCode'].some(k=>b[k]!=null)))return r.status(409).json({error:'Discount and code cannot be changed after redemption. Duplicate the offer instead.'});const allowed:any={discountType:'discount_type',discountValue:'discount_value',promoCode:'promo_code',title:'title',description:'description',category:'category',maximumDiscount:'maximum_discount',minimumFare:'minimum_fare',startAt:'start_at',expiresAt:'expires_at',travelStartAt:'travel_start_at',travelEndAt:'travel_end_at',usageLimit:'usage_limit',perUserLimit:'per_user_limit',eligibility:'eligibility',terms:'terms'};db.transaction(()=>{for(const[k,col]of Object.entries(allowed))if(b[k]!==undefined)db.prepare(`UPDATE offers SET ${col}=?,updated_at=? WHERE id=?`).run(k==='promoCode'?String(b[k]).toUpperCase():b[k],now(),id);if(b.promoCode)db.prepare('UPDATE promo_codes SET code=? WHERE offer_id=?').run(String(b.promoCode).toUpperCase(),id);syncOfferRelations(id,b);db.prepare("INSERT INTO offer_audit_logs(offer_id,admin_id,action,changed_fields,created_at) VALUES(?,?,'EDITED',?,?)").run(id,u.id,JSON.stringify(b),now())})();r.json(offers.get(id))});
app.post('/api/admin/offers/:id/duplicate',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});const src:any=db.prepare('SELECT * FROM offers WHERE id=?').get(q.params.id);if(!src)return r.status(404).json({error:'Offer not found'});const code=`${src.promo_code}-COPY-${Date.now().toString().slice(-4)}`;const id=Number(db.transaction(()=>{const x=Number(db.prepare(`INSERT INTO offers(title,description,category,discount_type,discount_value,maximum_discount,minimum_fare,maximum_fare,promo_code,start_at,expires_at,booking_start_at,booking_end_at,travel_start_at,travel_end_at,status,usage_limit,per_user_limit,eligibility,weekend_only,terms,created_by,created_at,updated_at) SELECT title||' Copy',description,category,discount_type,discount_value,maximum_discount,minimum_fare,maximum_fare,?,start_at,expires_at,booking_start_at,booking_end_at,travel_start_at,travel_end_at,'DISABLED',usage_limit,per_user_limit,eligibility,weekend_only,terms,?,?,? FROM offers WHERE id=?`).run(code,u.id,now(),now(),src.id).lastInsertRowid);db.prepare('INSERT INTO promo_codes(offer_id,code,active) VALUES(?,?,0)').run(x,code);db.prepare('INSERT INTO offer_routes(offer_id,origin,destination) SELECT ?,origin,destination FROM offer_routes WHERE offer_id=?').run(x,src.id);db.prepare('INSERT INTO offer_airlines(offer_id,airline) SELECT ?,airline FROM offer_airlines WHERE offer_id=?').run(x,src.id);db.prepare('INSERT INTO offer_cabins(offer_id,cabin) SELECT ?,cabin FROM offer_cabins WHERE offer_id=?').run(x,src.id);db.prepare("INSERT INTO offer_audit_logs(offer_id,admin_id,action,changed_fields,created_at) VALUES(?,?,'DUPLICATED',?,?)").run(x,u.id,JSON.stringify({source:src.id}),now());return x})());r.json(offers.get(id))});
app.post('/api/admin/offers/:id/activate',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});const current=offers.get(q.params.id);if(!current)return r.status(404).json({error:'Offer not found'});if(current.status==='EXPIRED')return r.status(422).json({error:'Expired offers cannot be activated. Extend the expiry date first.'});db.prepare("UPDATE offers SET status='ACTIVE',updated_at=? WHERE id=?").run(now(),q.params.id);db.prepare('UPDATE promo_codes SET active=1 WHERE offer_id=?').run(q.params.id);db.prepare("INSERT INTO offer_audit_logs(offer_id,admin_id,action,changed_fields,created_at) VALUES(?,?,'ACTIVATED','{}',?)").run(q.params.id,u.id,now());r.json(offers.get(q.params.id))});
app.post('/api/admin/offers/:id/deactivate',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});db.prepare("UPDATE offers SET status='DISABLED',updated_at=? WHERE id=?").run(now(),q.params.id);db.prepare('UPDATE promo_codes SET active=0 WHERE offer_id=?').run(q.params.id);db.prepare("INSERT INTO offer_audit_logs(offer_id,admin_id,action,changed_fields,created_at) VALUES(?,?,'DEACTIVATED','{}',?)").run(q.params.id,u.id,now());r.json(offers.get(q.params.id))});
app.delete('/api/admin/offers/:id',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});db.prepare("UPDATE offers SET status='ARCHIVED',updated_at=? WHERE id=?").run(now(),q.params.id);db.prepare('UPDATE promo_codes SET active=0 WHERE offer_id=?').run(q.params.id);db.prepare("INSERT INTO offer_audit_logs(offer_id,admin_id,action,changed_fields,created_at) VALUES(?,?,'ARCHIVED','{}',?)").run(q.params.id,u.id,now());r.json({archived:true})});
app.get('/api/admin/offers/analytics',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;r.json(offers.analytics())});
function adminPermissionFor(method:string,path:string){const action=method==='GET'?'VIEW':method==='POST'?'CREATE':method==='DELETE'?'DELETE':'UPDATE';if(path.startsWith('/rbac/'))return null;if(path==='/stats')return['DASHBOARD','VIEW'];if(path.startsWith('/bookings'))return['BOOKINGS',action==='CREATE'?'UPDATE':action];if(path.startsWith('/offers'))return['OFFERS',path.includes('activate')||path.includes('deactivate')?'PUBLISH':action];if(path.startsWith('/waitlist'))return['WAITLIST',method==='GET'?'VIEW':'MANAGE'];if(path.startsWith('/navigation'))return['AIRPORT_NAVIGATION',method==='GET'?'VIEW':'UPDATE'];if(path.startsWith('/journeys'))return['MY_JOURNEY',method==='GET'?'VIEW':'UPDATE'];if(path.startsWith('/flights'))return['FLIGHTS',action];if(path.startsWith('/notifications'))return['NOTIFICATIONS','VIEW'];if(path.startsWith('/announcements'))return['ANNOUNCEMENTS',action];return['DASHBOARD','VIEW']}
app.use('/api/admin',(q,r,next)=>{const map=adminPermissionFor(q.method,q.path);if(!map)return next();if(!requirePermission(q,r,map[0],map[1]))return;next()});
app.get('/api/admin/rbac/modules',(q,r)=>{if(!requirePermission(q,r,'PERMISSIONS','VIEW'))return;r.json(db.prepare('SELECT * FROM rbac_modules WHERE active=1 ORDER BY code').all())});
app.get('/api/admin/rbac/permissions',(q,r)=>{if(!requirePermission(q,r,'PERMISSIONS','VIEW'))return;r.json(db.prepare('SELECT p.*,m.code module FROM rbac_permissions p JOIN rbac_modules m ON m.id=p.module_id WHERE p.active=1 ORDER BY m.code,p.action').all())});
app.get('/api/admin/rbac/roles',(q,r)=>{if(!requirePermission(q,r,'ROLES','VIEW'))return;r.json(db.prepare(`SELECT r.*,count(DISTINCT ur.user_id) users,count(DISTINCT rp.permission_id) permissions FROM rbac_roles r LEFT JOIN rbac_user_roles ur ON ur.role_id=r.id LEFT JOIN rbac_role_permissions rp ON rp.role_id=r.id GROUP BY r.id ORDER BY r.code`).all())});
app.post('/api/admin/rbac/roles',(q,r)=>{const u=requirePermission(q,r,'ROLES','CREATE');if(!u)return;const code=String(q.body.code||'').toUpperCase().replace(/[^A-Z0-9_]/g,'');if(!code||['SUPER_ADMIN','ADMIN','CUSTOMER'].includes(code))return r.status(422).json({error:'Invalid or protected role code'});try{const id=Number(db.prepare('INSERT INTO rbac_roles(code,name,active,system_role,created_at,updated_at) VALUES(?,?,1,0,?,?)').run(code,q.body.name||code,now(),now()).lastInsertRowid);authorization.audit(u.id,'ROLES','CREATE','ROLE',id,'SUCCESS',{code});r.status(201).json(db.prepare('SELECT * FROM rbac_roles WHERE id=?').get(id))}catch(e:any){r.status(409).json({error:'Role code already exists'})}});
app.put('/api/admin/rbac/roles/:id/permissions',(q,r)=>{const u=requirePermission(q,r,'PERMISSIONS','ASSIGN');if(!u)return;const role:any=db.prepare('SELECT * FROM rbac_roles WHERE id=?').get(q.params.id);if(!role)return r.status(404).json({error:'Role not found'});if(role.code==='SUPER_ADMIN')return r.status(422).json({error:'System Super Admin permissions cannot be reduced'});const codes=Array.isArray(q.body.permissions)?q.body.permissions:[];db.transaction(()=>{db.prepare('DELETE FROM rbac_role_permissions WHERE role_id=?').run(role.id);for(const code of codes)db.prepare('INSERT INTO rbac_role_permissions(role_id,permission_id,granted_by,created_at) SELECT ?,id,?,? FROM rbac_permissions WHERE code=?').run(role.id,u.id,now(),code);const users=db.prepare('SELECT user_id FROM rbac_user_roles WHERE role_id=?').all(role.id)as any[];for(const x of users)authorization.bump(x.user_id);authorization.audit(u.id,'PERMISSIONS','ASSIGN','ROLE',role.id,'SUCCESS',{codes})})();r.json({ok:true})});
app.get('/api/admin/rbac/admins',(q,r)=>{if(!requirePermission(q,r,'ADMINS','VIEW'))return;r.json(db.prepare(`SELECT u.id,u.name,u.email,u.account_status,u.created_at,group_concat(r.code) roles FROM users u JOIN rbac_user_roles ur ON ur.user_id=u.id JOIN rbac_roles r ON r.id=ur.role_id WHERE r.code<>'CUSTOMER' GROUP BY u.id ORDER BY u.id`).all())});
app.post('/api/admin/rbac/admins',(q,r)=>{const u=requirePermission(q,r,'ADMINS','CREATE');if(!u)return;const role:any=db.prepare('SELECT * FROM rbac_roles WHERE code=? AND active=1').get(String(q.body.role||'ADMIN'));if(!role||role.code==='SUPER_ADMIN')return r.status(403).json({error:'Cannot create or assign Super Admin through this operation'});if(!q.body.email||String(q.body.password||'').length<10)return r.status(422).json({error:'Valid email and 10+ character temporary password required'});try{const id=Number(db.prepare("INSERT INTO users(name,email,phone,password_hash,role,account_status,must_change_password,created_at) VALUES(?,?,?,?,'ADMIN','ACTIVE',1,?)").run(q.body.name,q.body.email,'',hash(q.body.password),now()).lastInsertRowid);db.prepare('INSERT INTO rbac_user_roles(user_id,role_id,assigned_by,created_at) VALUES(?,?,?,?)').run(id,role.id,u.id,now());authorization.bump(id);authorization.audit(u.id,'ADMINS','CREATE','USER',id,'SUCCESS',{role:role.code});r.status(201).json({id,email:q.body.email,role:role.code})}catch(e:any){r.status(409).json({error:'Admin email already exists'})}});
app.put('/api/admin/rbac/admins/:id/role',(q,r)=>{const u=requirePermission(q,r,'ROLES','ASSIGN');if(!u)return;const target=Number(q.params.id),currentRoles=authorization.roles(target),role:any=db.prepare('SELECT * FROM rbac_roles WHERE code=? AND active=1').get(q.body.role);if(!role)return r.status(404).json({error:'Role not found'});if(target===u.id)return r.status(403).json({error:'Self authorization changes are not allowed'});if(currentRoles.includes('SUPER_ADMIN')&&role.code!=='SUPER_ADMIN'){const count=(db.prepare("SELECT count(DISTINCT ur.user_id) c FROM rbac_user_roles ur JOIN rbac_roles rr ON rr.id=ur.role_id JOIN users uu ON uu.id=ur.user_id WHERE rr.code='SUPER_ADMIN' AND rr.active=1 AND uu.account_status='ACTIVE'").get()as any).c;if(count<=1)return r.status(409).json({error:'Cannot remove the final active Super Admin'})}if(role.code==='SUPER_ADMIN'&&!authorization.hasRole(u.id,'SUPER_ADMIN'))return r.status(403).json({error:'Only Super Admin can assign Super Admin'});db.transaction(()=>{db.prepare('DELETE FROM rbac_user_roles WHERE user_id=?').run(target);db.prepare('INSERT INTO rbac_user_roles(user_id,role_id,assigned_by,created_at) VALUES(?,?,?,?)').run(target,role.id,u.id,now());authorization.bump(target);authorization.audit(u.id,'ROLES','ASSIGN','USER',target,'SUCCESS',{role:role.code})})();r.json({ok:true})});
app.put('/api/admin/rbac/admins/:id/status',(q,r)=>{const target=Number(q.params.id),status=q.body.status==='ACTIVE'?'ACTIVE':'SUSPENDED',u=requirePermission(q,r,'ADMINS',status==='ACTIVE'?'ACTIVATE':'SUSPEND');if(!u)return;if(target===u.id)return r.status(403).json({error:'Cannot change your own account status'});if(status==='SUSPENDED'&&authorization.hasRole(target,'SUPER_ADMIN')){const count=(db.prepare("SELECT count(DISTINCT ur.user_id) c FROM rbac_user_roles ur JOIN rbac_roles rr ON rr.id=ur.role_id JOIN users uu ON uu.id=ur.user_id WHERE rr.code='SUPER_ADMIN' AND uu.account_status='ACTIVE'").get()as any).c;if(count<=1)return r.status(409).json({error:'Cannot suspend the final active Super Admin'})}db.transaction(()=>{db.prepare('UPDATE users SET account_status=? WHERE id=?').run(status,target);if(status==='SUSPENDED')db.prepare('DELETE FROM sessions WHERE user_id=?').run(target);authorization.audit(u.id,'ADMINS',status==='ACTIVE'?'ACTIVATE':'SUSPEND','USER',target,'SUCCESS')})();r.json({status})});
app.delete('/api/admin/rbac/admins/:id/sessions',(q,r)=>{const u=requirePermission(q,r,'ADMINS','SESSION_REVOKE');if(!u)return;const target=Number(q.params.id);if(target===u.id)return r.status(403).json({error:'Use logout to revoke your own current session'});const count=db.prepare('DELETE FROM sessions WHERE user_id=?').run(target).changes;authorization.audit(u.id,'ADMINS','SESSION_REVOKE','USER',target,'SUCCESS',{sessions:count});r.json({revoked:count})});
app.put('/api/admin/rbac/admins/:id/permission',(q,r)=>{const u=requirePermission(q,r,'PERMISSIONS',q.body.effect==='DENY'?'REVOKE':'ASSIGN');if(!u)return;const target=Number(q.params.id);if(target===u.id)return r.status(403).json({error:'Self escalation is not allowed'});const p:any=db.prepare('SELECT id,code FROM rbac_permissions WHERE code=?').get(q.body.permission);if(!p)return r.status(404).json({error:'Permission not found'});const effect=q.body.effect==='DENY'?'DENY':'GRANT';db.prepare('INSERT INTO rbac_user_permissions(user_id,permission_id,effect,assigned_by,created_at) VALUES(?,?,?,?,?) ON CONFLICT(user_id,permission_id) DO UPDATE SET effect=excluded.effect,assigned_by=excluded.assigned_by,created_at=excluded.created_at').run(target,p.id,effect,u.id,now());authorization.bump(target);authorization.audit(u.id,'PERMISSIONS',effect==='DENY'?'REVOKE':'ASSIGN','USER',target,'SUCCESS',{permission:p.code,effect});r.json({ok:true,version:authorization.version(target)})});
app.delete('/api/admin/rbac/admins/:id/permission/:code',(q,r)=>{const u=requirePermission(q,r,'PERMISSIONS','REVOKE');if(!u)return;const target=Number(q.params.id);if(target===u.id)return r.status(403).json({error:'Self authorization changes are not allowed'});const p:any=db.prepare('SELECT id FROM rbac_permissions WHERE code=?').get(q.params.code);if(!p)return r.status(404).json({error:'Permission not found'});db.prepare('DELETE FROM rbac_user_permissions WHERE user_id=? AND permission_id=?').run(target,p.id);authorization.bump(target);authorization.audit(u.id,'PERMISSIONS','REVOKE','USER',target,'SUCCESS',{permission:q.params.code,overrideRemoved:true});r.json({ok:true})});
app.get('/api/admin/rbac/admins/:id/effective-permissions',(q,r)=>{if(!requirePermission(q,r,'ADMINS','VIEW'))return;r.json({roles:authorization.roles(Number(q.params.id)),permissions:authorization.permissions(Number(q.params.id)),version:authorization.version(Number(q.params.id))})});
app.get('/api/admin/rbac/audit-logs',(q,r)=>{if(!requirePermission(q,r,'AUDIT_LOGS','VIEW'))return;const limit=Math.min(200,Number(q.query.limit||50));r.json(db.prepare('SELECT * FROM rbac_audit_logs ORDER BY id DESC LIMIT ?').all(limit))});
app.get('/api/health',(_,r)=>r.json({ok:true,aviationProvider:amadeus.configured?'AMADEUS':'DEMO_DYNAMIC'}));
app.get('/api/airports',async(q,r)=>{const keyword=String(q.query.q||'').trim();let local:any[]=keyword?db.prepare("SELECT iata,name,city,country,country_code countryCode,latitude lat,longitude lon,source FROM airports WHERE iata LIKE ? OR city LIKE ? OR name LIKE ? OR country LIKE ? ORDER BY CASE WHEN iata=? THEN 0 WHEN city LIKE ? THEN 1 ELSE 2 END LIMIT 25").all(`${keyword.toUpperCase()}%`,`%${keyword}%`,`%${keyword}%`,`%${keyword}%`,keyword.toUpperCase(),`${keyword}%`):db.prepare("SELECT iata,name,city,country,country_code countryCode,latitude lat,longitude lon,source FROM airports ORDER BY CASE WHEN country_code='IN' THEN 0 ELSE 1 END,city LIMIT 30").all();if(amadeus.configured&&keyword.length>=2){try{const live=await amadeus.airports(keyword);for(const a of live)airportInsert.run(a.iata,a.name,a.city,a.country,a.countryCode,a.lat??null,a.lon??null);const seen=new Set(live.map(x=>x.iata));local=[...live,...local.filter(x=>!seen.has(x.iata))].slice(0,25)}catch(e){console.warn('Airport provider fallback:',(e as Error).message)}}r.json({data:local,provider:amadeus.configured?'AMADEUS_WITH_CATALOG_FALLBACK':'CATALOG',coverage:amadeus.configured?'GLOBAL_LIVE':'100+ MAJOR AIRPORTS'})});
