app.get('/api/flights/availability',(q,r)=>{const origin=String(q.query.origin||'').toUpperCase(),destination=String(q.query.destination||'').toUpperCase(),year=Number(q.query.year),month=Number(q.query.month);if(!origin||!destination||origin===destination||!year||!month)return r.status(422).json({error:'Origin, destination, month and year are required'});const dates=skyBookCalendar.month(year,month),w=skyBookCalendar.window(),rows=dates.map(date=>{if(date<w.minDate)return{date,state:'PAST'};if(date>w.maxDate)return{date,state:'OUTSIDE_BOOKING_WINDOW'};const fs=db.prepare(`SELECT f.fare,SUM(CASE WHEN s.status IN ('AVAILABLE','PREMIUM') THEN 1 ELSE 0 END) available FROM flights f LEFT JOIN seats s ON s.flight_id=f.id WHERE f.origin=? AND f.destination=? AND date(f.departure)=date(?) GROUP BY f.id`).all(origin,destination,date)as any[];if(!fs.length)return{date,state:'NO_FLIGHTS'};const available=fs.reduce((n,x)=>n+x.available,0),fare=Math.min(...fs.map(x=>x.fare));return{date,state:available===0?'SOLD_OUT':available<4?'LIMITED':'AVAILABLE',availableSeats:available,lowestFare:fare}});r.json({origin,destination,year,month,bookingWindow:w,dates:rows,source:'SKYBOOK_FLIGHT_INVENTORY'})});
