const loginAttempts=new Map<string,{count:number;reset:number}>();function loginRate(req:any,res:any){const key=String(req.ip||req.socket?.remoteAddress||'unknown'),n=Date.now(),x=loginAttempts.get(key);if(x&&x.reset>n&&x.count>=20){res.status(429).json({error:'Too many login attempts. Try again later.'});return false}if(!x||x.reset<=n)loginAttempts.set(key,{count:0,reset:n+15*60000});return true}function authenticateCredentials(email:string,password:string){const u:any=db.prepare('SELECT * FROM users WHERE lower(email)=lower(?) AND account_status<>\'SUSPENDED\'').get(email);if(!u)return null;const[salt,key]=u.password_hash.split(':');try{if(!timingSafeEqual(Buffer.from(key,'hex'),scryptSync(password,salt,64)))return null}catch{return null}return u}const adminRoles=['AIRLINE_ADMIN','SYSTEM_ADMIN','ADMIN','SUPER_ADMIN','OPERATIONS','SUPPORT'];
