app.post('/api/payments/create-order',async(q,r)=>{const u=identity(q);if(!u)return r.status(401).json({error:'Authentication required'});if(!paymentGateway.configured)return r.status(503).json({error:'Payment gateway is not configured. Booking payment is unavailable.'});const b=q.body||{},flight:any=db.prepare('SELECT * FROM flights WHERE id=?').get(b.flightId),seat:any=db.prepare('SELECT * FROM seats WHERE flight_id=? AND label=?').get(b.flightId,b.seat);if(!flight||!seat||!['AVAILABLE','PREMIUM'].includes(seat.status))return r.status(409).json({error:'Selected inventory is unavailable'});const tiers:any={Saver:0,Standard:900,Flex:1900,Business:8200};if(tiers[b.fareTier]===undefined)return r.status(422).json({error:'Invalid fare tier'});const fare=flight.fare+tiers[b.fareTier],user:any=db.prepare('SELECT id,email,role,student_status studentStatus FROM users WHERE id=?').get(u.id);let offer:any=null;if(b.promoCode){const v=offers.validate(b.promoCode,{user,flight,cabin:b.fareTier==='Business'?'BUSINESS':'ECONOMY',fareAmount:fare,travelDate:flight.departure,passengers:1});if(!v.valid)return r.status(422).json(v);offer=v}const total=DiscountEngine.calculate({fare,offer:offer?.offer,taxes:756,serviceFee:200,seatFee:seat.price,addOns:b.extraBaggage?1200:0}).finalTotal,key=String(q.headers['idempotency-key']||'');if(!key)return r.status(422).json({error:'Idempotency-Key header required'});const prior:any=db.prepare('SELECT * FROM payment_orders WHERE idempotency_key=? AND user_id=?').get(key,u.id);if(prior)return r.json(prior);const hold=db.prepare("UPDATE seats SET status='HELD' WHERE id=? AND status IN ('AVAILABLE','PREMIUM')").run(seat.id);if(hold.changes!==1)return r.status(409).json({error:'Seat hold conflict'});try{const ref=`SB-ORDER-${randomBytes(6).toString('hex').toUpperCase()}`,gateway:any=await paymentGateway.createOrder({amount:total,currency:'INR',receipt:ref,notes:{userId:String(u.id),flightId:String(flight.id)}}),expires=new Date(Date.now()+10*60000).toISOString(),id=Number(db.prepare("INSERT INTO payment_orders(order_ref,user_id,flight_id,seat_label,fare_tier,extra_baggage,promo_code,amount,currency,status,gateway,gateway_order_id,idempotency_key,hold_expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'CREATED','RAZORPAY',?,?,?,?,?)").run(ref,u.id,flight.id,seat.label,b.fareTier,b.extraBaggage?1:0,b.promoCode||null,total,'INR',gateway.id,key,expires,now(),now()).lastInsertRowid);r.status(201).json({id,orderRef:ref,gatewayOrderId:gateway.id,keyId:(paymentGateway as any).keyId,amount:total,currency:'INR',holdExpiresAt:expires,methods:paymentGateway.getSupportedMethods()})}catch(e:any){db.prepare("UPDATE seats SET status='AVAILABLE' WHERE id=? AND status='HELD'").run(seat.id);r.status(e.status||502).json({error:e.message})}});
app.post('/api/bookings',(q,r)=>{const u=identity(q);if(!u)return r.status(401).json({error:'Authentication required'});const {flightId,name,email,seat,fareTier,extraBaggage=false,promoCode,expectedFare}=q.body;try{if(!flightId||!name||!email||!seat)throw Error('Validated passenger, flight and seat details are required');if(email!==u.email)throw Error('Booking contact must match the authenticated demo passenger');const out=db.transaction(()=>{const s:any=db.prepare('SELECT * FROM seats WHERE flight_id=? AND label=?').get(flightId,seat);const f:any=db.prepare('SELECT * FROM flights WHERE id=?').get(flightId);if(!f||!s||!['AVAILABLE','PREMIUM'].includes(s.status))throw Error('Seat is no longer available');const dateCheck=skyBookCalendar.validate({departureDate:String(f.departure).slice(0,10)});if(!dateCheck.valid)throw Error(dateCheck.errors.join(' '));if(Date.parse(f.departure)<=Date.now())throw Error('This flight has already departed and cannot be booked.');if(expectedFare!=null&&Number(expectedFare)!==Number(f.fare))throw Error(`Fare updated. New base fare is ₹${Number(f.fare).toLocaleString('en-IN')}. Review and confirm the new total.`);const update=db.prepare("UPDATE seats SET status='OCCUPIED' WHERE id=? AND status IN ('AVAILABLE','PREMIUM')").run(s.id);if(update.changes!==1)throw Error('Seat allocation conflict; please select another seat');const surcharge:Record<string,number>={Saver:0,Standard:900,Flex:1900,Business:8200};if(!(fareTier in surcharge))throw Error('Invalid fare tier');const fareAmount=f.fare+surcharge[fareTier],addOns=extraBaggage?1200:0,user:any=db.prepare('SELECT id,email,role,student_status studentStatus FROM users WHERE id=?').get(u.id);let validation:any=null;if(promoCode){validation=offers.validate(String(promoCode),{user,flight:f,cabin:fareTier==='Business'?'BUSINESS':'ECONOMY',fareAmount,travelDate:f.departure,bookingDate:now(),passengers:1});if(!validation.valid)throw Error(validation.reasons.join(' '))}const breakdown=DiscountEngine.calculate({fare:fareAmount,offer:validation?.offer,taxes:756,serviceFee:200,seatFee:s.price,addOns}),total=breakdown.finalTotal,originalTotal=fareAmount+756+200+s.price+addOns;const code=pnr();const id=Number(db.prepare("INSERT INTO bookings(pnr,user_name,user_email,flight_id,seat,fare_tier,total,status,payment_status,created_at,original_fare,discount_amount,offer_id) VALUES(?,?,?,?,?,?,?,'CONFIRMED','SUCCESS',?,?,?,?)").run(code,name,email,flightId,seat,fareTier,total,now(),originalTotal,breakdown.discount,validation?.offer?.id||null).lastInsertRowid);db.prepare("INSERT INTO booking_seats(booking_id,flight_id,seat_label,status,created_at,updated_at) VALUES(?,?,?,'ACTIVE',?,?)").run(id,flightId,seat,now(),now());if(validation?.offer)offers.redeem(validation.offer.id,u.id,id,breakdown.discount);const tn=ticket(),transactionId=`TXN-${randomBytes(6).toString('hex').toUpperCase()}`;db.prepare('INSERT INTO tickets(booking_id,ticket_no,created_at) VALUES(?,?,?)').run(id,tn,now());db.prepare("INSERT INTO payments(booking_id,amount,method,status,transaction_id,created_at) VALUES(?,?,'DEMO','SUCCESS',?,?)").run(id,total,transactionId,now());db.prepare("INSERT INTO notifications(recipient,category,message,created_at) VALUES(?,'BOOKING',?,?)").run(email,validation?.offer?`Booking ${code} confirmed. You saved ₹${breakdown.discount.toLocaleString('en-IN')} with ${validation.offer.promo_code}.`:`Booking ${code} confirmed. Seat ${seat} is yours.`,now());return{id,pnr:code,ticketNo:tn,transactionId,total,savings:breakdown.discount,promoCode:validation?.offer?.promo_code||null,breakdown}})();r.json(out)}catch(e:any){r.status(409).json({error:e.message})}});
const bookingListSql='SELECT b.*,f.number,f.origin,f.destination,f.departure,f.arrival,f.terminal,f.gate,f.status flight_status,f.baggage,t.ticket_no FROM bookings b JOIN flights f ON f.id=b.flight_id LEFT JOIN tickets t ON t.booking_id=b.id'; app.get('/api/bookings',(q,r)=>{const u=identity(q);if(!u)return r.status(401).json({error:'Authentication required'});r.json(db.prepare(bookingListSql+' WHERE b.user_email=? ORDER BY b.id DESC').all(u.email))}); app.get('/api/bookings/:id/payment',(q,r)=>{const u=identity(q);if(!u)return r.status(401).json({error:'Authentication required'});const x:any=db.prepare('SELECT p.amount,p.method,p.status,p.transaction_id,b.user_email FROM payments p JOIN bookings b ON b.id=p.booking_id WHERE p.booking_id=?').get(q.params.id);if(!x)return r.status(404).json({error:'Payment not found'});if(x.user_email!==u.email&&!['AIRLINE_ADMIN','SYSTEM_ADMIN'].includes(u.role))return r.status(403).json({error:'Not authorized'});delete x.user_email;r.json(x)}); app.get('/api/admin/bookings',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;r.json(db.prepare(bookingListSql+' ORDER BY b.id DESC').all())});
