app.post('/api/admin/waitlist/flight/:flightId/schedule',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true||!q.body.departure)return r.status(428).json({error:'Confirmed departure time required'});db.transaction(()=>{db.prepare('UPDATE flights SET departure=? WHERE id=?').run(q.body.departure,q.params.flightId);const rows=db.prepare("SELECT w.*,u.email FROM waitlist_entries w JOIN users u ON u.id=w.user_id WHERE w.flight_id=? AND w.status='ACTIVE'").all(q.params.flightId)as any[];for(const x of rows){db.prepare("INSERT INTO waitlist_events(waitlist_id,user_id,flight_id,event_type,metadata,created_at) VALUES(?,?,?,'FLIGHT_SCHEDULE_CHANGED',?,?)").run(x.id,x.user_id,x.flight_id,JSON.stringify({departure:q.body.departure,requiresAcknowledgement:true}),now());db.prepare("INSERT INTO notifications(recipient,category,message,created_at) VALUES(?,'WAITLIST',?,?)").run(x.email,`The flight schedule changed to ${q.body.departure}. Review whether you want to remain waitlisted.`,now())}})();smartWaitlist.expireFlightEntries();r.json({updated:true})});
