app.post('/api/admin/waitlist/:id/retry-promotion',(q,r)=>{const u=requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']);if(!u)return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});const x:any=smartWaitlist.get(u,Number(q.params.id));if(!x)return r.status(404).json({error:'Entry not found'});db.prepare("UPDATE waitlist_entries SET status='ACTIVE',updated_at=? WHERE id=? AND status IN ('PAYMENT_FAILED','DECLINED','EXPIRED')").run(now(),x.id);smartWaitlist.updatePositions(x.flight_id);db.prepare("INSERT INTO waitlist_events(waitlist_id,user_id,flight_id,event_type,metadata,created_at) VALUES(?,?,?,'ADMIN_RETRY',?,?)").run(x.id,x.user_id,x.flight_id,JSON.stringify({adminId:u.id}),now());r.json(smartWaitlist.processAvailableSeats(x.flight_id,`admin-retry:${x.id}:${Date.now()}`))});
function setupSmartWaitlistDemo(){return db.transaction(()=>{const f:any=db.prepare("SELECT * FROM flights WHERE number='SK102'").get();if(!f)throw Error('SK102 not found');const bids=(db.prepare('SELECT id FROM bookings WHERE flight_id=?').all(f.id)as any[]).map(x=>x.id);for(const bid of bids){db.prepare('DELETE FROM offer_redemptions WHERE booking_id=?').run(bid);db.prepare('DELETE FROM refunds WHERE booking_id=?').run(bid);db.prepare('DELETE FROM payments WHERE booking_id=?').run(bid);db.prepare('DELETE FROM tickets WHERE booking_id=?').run(bid);db.prepare('DELETE FROM journeys WHERE booking_id=?').run(bid);db.prepare('DELETE FROM booking_seats WHERE booking_id=?').run(bid)}db.prepare('DELETE FROM waitlist_events WHERE flight_id=?').run(f.id);db.prepare('DELETE FROM waitlist_promotions WHERE flight_id=?').run(f.id);db.prepare('DELETE FROM waitlist_entries WHERE flight_id=?').run(f.id);db.prepare('DELETE FROM bookings WHERE flight_id=?').run(f.id);db.prepare('DELETE FROM seats WHERE flight_id=?').run(f.id);db.prepare("UPDATE flights SET capacity=5,fare=5500,status='ON_TIME',terminal='T2',gate='24' WHERE id=?").run(f.id);const labels=['11A','11B','12A','12B','13A'];for(const label of labels)db.prepare("INSERT INTO seats(flight_id,label,status,price) VALUES(?,?,'OCCUPIED',500)").run(f.id,label);for(let i=0;i<5;i++){const name=`Passenger ${String.fromCharCode(65+i)}`,email=`passenger${String.fromCharCode(97+i)}@demo.com`,code=`DEMOA${i+1}`,bid=Number(db.prepare("INSERT INTO bookings(pnr,user_name,user_email,flight_id,seat,fare_tier,total,status,payment_status,created_at,original_fare,discount_amount) VALUES(?,?,?,?,?,'Standard',5000,'CONFIRMED','SUCCESS',?,5000,0)").run(code,name,email,f.id,labels[i],now()).lastInsertRowid);db.prepare("INSERT INTO booking_seats(booking_id,flight_id,seat_label,status,created_at,updated_at) VALUES(?,?,?,'ACTIVE',?,?)").run(bid,f.id,labels[i],now(),now());db.prepare('INSERT INTO tickets(booking_id,ticket_no,created_at) VALUES(?,?,?)').run(bid,`SK-DEMO-${i+1}`,now());db.prepare("INSERT INTO payments(booking_id,amount,method,status,transaction_id,created_at) VALUES(?,5000,'DEMO','SUCCESS',?,?)").run(bid,`TXN-DEMO-${i+1}-${Date.now()}`,now())}const joined=[new Date(Date.now()-180000).toISOString(),new Date(Date.now()-120000).toISOString(),new Date(Date.now()-60000).toISOString()];for(const [i,email,max]of [[0,'passengerf@demo.com',6000],[1,'passengerg@demo.com',5500],[2,'passengerh@demo.com',7000]]as any[]){const u:any=db.prepare('SELECT id FROM users WHERE email=?').get(email),id=Number(db.prepare(`INSERT INTO waitlist_entries(user_id,flight_id,passenger_count,cabin,max_fare_authorized,status,position,joined_at,expires_at,priority_score,notification_preferences,allow_partial,seat_preference,authorization_status,created_at,updated_at) VALUES(?, ?,1,'ECONOMY',?,'ACTIVE',?,?,?,0,'{"inApp":true}',0,'WINDOW','AUTHORIZED',?,?)`).run(u.id,f.id,max,i+1,joined[i],'2026-08-20T09:30:00.000Z',joined[i],joined[i]).lastInsertRowid);db.prepare("INSERT INTO waitlist_events(waitlist_id,user_id,flight_id,event_type,metadata,created_at) VALUES(?,?,?,'JOINED',?,?)").run(id,u.id,f.id,JSON.stringify({seededDemo:true,maxFare:max}),joined[i])}db.prepare("INSERT INTO waitlist_config(flight_id,policy,promotion_window_minutes,max_passengers,payment_failure_policy,partial_confirmation,updated_at) VALUES(?,'FIFO',15,6,'RELEASE_AND_NEXT',0,?) ON CONFLICT(flight_id) DO UPDATE SET policy='FIFO',promotion_window_minutes=15,updated_at=excluded.updated_at").run(f.id,now());return{flightId:f.id,flightNumber:f.number,capacity:5,queue:smartWaitlist.list({id:0,role:'SYSTEM_ADMIN'})}})()}
app.post('/api/demo/waitlist/reset',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});try{r.json(setupSmartWaitlistDemo())}catch(e:any){r.status(409).json({error:e.message})}});
