app.post('/api/demo/waitlist/release-seats',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;if(q.body?.confirmed!==true||!Array.isArray(q.body.labels))return r.status(428).json({error:'Confirmed seat labels required'});const f:any=db.prepare("SELECT id FROM flights WHERE number='SK102'").get();db.transaction(()=>{for(const label of q.body.labels){const bs:any=db.prepare("SELECT booking_id FROM booking_seats WHERE flight_id=? AND seat_label=? AND status='ACTIVE'").get(f.id,label);if(bs){const b:any=db.prepare("SELECT total FROM bookings WHERE id=? AND status='CONFIRMED'").get(bs.booking_id);if(b){const fee=Math.min(500,Math.round(b.total*.1));db.prepare("UPDATE bookings SET status='CANCELLED' WHERE id=?").run(bs.booking_id);db.prepare("UPDATE booking_seats SET status='RELEASED',updated_at=? WHERE booking_id=? AND seat_label=?").run(now(),bs.booking_id,label);db.prepare("INSERT INTO refunds(booking_id,amount,fee,status,created_at) VALUES(?,?,?,'INITIATED',?)").run(bs.booking_id,b.total-fee,fee,now())}}db.prepare("UPDATE seats SET status='AVAILABLE' WHERE flight_id=? AND label=? AND status='OCCUPIED'").run(f.id,label)}})();const results=q.body.process===false?[]:smartWaitlist.processAllAvailableSeats(f.id,String(q.body.idempotencyKey||`release:${Date.now()}`));r.json({released:q.body.labels,results})});
app.post('/api/demo/waitlist/cancel-passenger',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});const name=String(q.body.passenger||'A').toUpperCase().replace('PASSENGER ','').slice(0,1),b:any=db.prepare("SELECT id FROM bookings WHERE user_name=? AND status='CONFIRMED' AND flight_id=(SELECT id FROM flights WHERE number='SK102')").get(`Passenger ${name}`);if(!b)return r.status(404).json({error:`Passenger ${name} booking not found`});try{r.json(cancelAndRecover(b.id))}catch(e:any){r.status(409).json({error:e.message})}});
