app.post('/api/demo/waitlist/expire-promotion',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Confirmation required'});r.json(smartWaitlist.expirePromotion(Number(q.body.promotionId)))});
const waitlistSql="SELECT w.*,f.number,f.origin,f.destination,f.fare, ROW_NUMBER() OVER(PARTITION BY w.flight_id ORDER BY w.created_at,w.id) position FROM waitlist w JOIN flights f ON f.id=w.flight_id WHERE w.status='WAITING'"; app.get('/api/legacy-waitlist',(q,r)=>{const u=identity(q),email=q.query.public==='1'?'':u?.email||'';const rows:any[]=email?db.prepare(waitlistSql+" AND w.email=? ORDER BY w.created_at,w.id").all(email) as any[]:db.prepare(waitlistSql+" ORDER BY w.created_at,w.id").all() as any[];r.json(rows.map(x=>({...x,name:email?x.name:`${x.name[0]}${'*'.repeat(Math.max(2,x.name.length-2))}${x.name.slice(-1)}`,email:undefined}))) }); app.get('/api/admin/legacy-waitlist',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;r.json(db.prepare(waitlistSql+" ORDER BY w.created_at,w.id").all())});
app.post('/api/legacy-waitlist',(q,r)=>{const {flightId,name,email,maxFare}=q.body;const id=db.prepare("INSERT INTO waitlist(flight_id,name,email,max_fare,seats,status,created_at) VALUES(?,?,?,?,1,'WAITING',?)").run(flightId,name,email,maxFare,now()).lastInsertRowid;r.json({id,status:'WAITING'})});
function cancelAndRecover(bookingId:number){return db.transaction(()=>{const b:any=db.prepare("SELECT b.*,f.fare,f.status flight_status FROM bookings b JOIN flights f ON f.id=b.flight_id WHERE b.id=? AND b.status='CONFIRMED'").get(bookingId);if(!b)throw Error('Confirmed booking not found');const fee=Math.min(500,Math.round(b.total*.1)),amount=b.total-fee;db.prepare("UPDATE bookings SET status='CANCELLED' WHERE id=?").run(b.id);db.prepare("UPDATE booking_seats SET status='RELEASED',updated_at=? WHERE booking_id=? AND status='ACTIVE'").run(now(),b.id);db.prepare("INSERT INTO refunds(booking_id,amount,fee,status,created_at) VALUES(?,?,?,'INITIATED',?)").run(b.id,amount,fee,now());const released=db.prepare("UPDATE seats SET status='AVAILABLE' WHERE flight_id=? AND label=? AND status='OCCUPIED'").run(b.flight_id,b.seat);if(released.changes!==1)throw Error('Seat release conflict; cancellation rolled back');const smartActive=(db.prepare("SELECT count(*) c FROM waitlist_entries WHERE flight_id=? AND status='ACTIVE'").get(b.flight_id)as any).c;if(smartActive){const promotion=smartWaitlist.processAvailableSeats(b.flight_id,`cancellation:${b.id}`,b.seat);db.prepare('INSERT INTO audit_logs(action,detail,created_at) VALUES(?,?,?)').run('SMART_WAITLIST_PROMOTION',JSON.stringify({cancelled:b.pnr,seat:b.seat,promotion}),now());return{cancelled:b.pnr,refund:{amount,fee,status:'INITIATED'},seat:b.seat,promotion}}if(b.flight_status==='CANCELLED')return{cancelled:b.pnr,refund:{amount,fee,status:'INITIATED'},seat:b.seat,recovery:null};const eligible:any=db.prepare("SELECT * FROM waitlist WHERE flight_id=? AND status='WAITING' AND seats=1 AND max_fare>=? ORDER BY created_at,id LIMIT 1").get(b.flight_id,b.fare);let recovery:any=null;if(eligible){const reserved=db.prepare("UPDATE seats SET status='OCCUPIED' WHERE flight_id=? AND label=? AND status='AVAILABLE'").run(b.flight_id,b.seat);if(reserved.changes!==1)throw Error('Released seat was concurrently claimed; recovery rolled back');const code=pnr();const nb=Number(db.prepare("INSERT INTO bookings(pnr,user_name,user_email,flight_id,seat,fare_tier,total,status,payment_status,created_at) VALUES(?,?,?,?,?,'Standard',?,'CONFIRMED','SUCCESS',?)").run(code,eligible.name,eligible.email,b.flight_id,b.seat,b.fare,now()).lastInsertRowid);db.prepare("INSERT INTO booking_seats(booking_id,flight_id,seat_label,status,created_at,updated_at) VALUES(?,?,?,'ACTIVE',?,?)").run(nb,b.flight_id,b.seat,now(),now());const tn=ticket(),tx=`TXN-${randomBytes(6).toString('hex').toUpperCase()}`;db.prepare('INSERT INTO tickets(booking_id,ticket_no,created_at) VALUES(?,?,?)').run(nb,tn,now());db.prepare("INSERT INTO payments(booking_id,amount,method,status,transaction_id,created_at) VALUES(?,?,'WAITLIST_AUTH','SUCCESS',?,?)").run(nb,b.fare,tx,now());db.prepare("UPDATE waitlist SET status='CONFIRMED' WHERE id=?").run(eligible.id);db.prepare("INSERT INTO notifications(recipient,category,message,created_at) VALUES(?,'WAITLIST',?,?)").run(eligible.email,`A seat opened up! ${b.seat} has been confirmed under PNR ${code}.`,now());recovery={passenger:eligible.name,pnr:code,seat:b.seat,ticketNo:tn,fare:b.fare}}
 db.prepare('INSERT INTO audit_logs(action,detail,created_at) VALUES(?,?,?)').run('SEAT_RECOVERY',JSON.stringify({cancelled:b.pnr,recovery}),now());return{cancelled:b.pnr,refund:{amount,fee,status:'INITIATED'},seat:b.seat,recovery}})()}
app.post('/api/bookings/:id/cancel',(q,r)=>{if(q.body?.confirmed!==true)return r.status(428).json({error:'Explicit cancellation confirmation is required'});const u=identity(q),owner:any=db.prepare('SELECT user_email FROM bookings WHERE id=?').get(q.params.id);if(!u)return r.status(401).json({error:'Authentication required'});if(!owner||owner.user_email!==u.email)return r.status(403).json({error:'You may cancel only your own booking'});try{r.json(cancelAndRecover(Number(q.params.id)))}catch(e:any){r.status(400).json({error:e.message})}});
