app.post('/api/demo/flight-update',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Explicit administrative confirmation is required'});const {type}=q.body;const f:any=db.prepare("SELECT * FROM flights WHERE number='SK102'").get();if(type==='delay'){db.prepare("UPDATE flights SET status='DELAYED' WHERE id=?").run(f.id);db.prepare("INSERT INTO notifications(recipient,category,message,created_at) VALUES('all','FLIGHT','SK102 is delayed by 35 minutes.',?)").run(now())}else{db.prepare("UPDATE flights SET gate='A12',terminal='T1' WHERE id=?").run(f.id);db.prepare("INSERT INTO notifications(recipient,category,message,created_at) VALUES('all','FLIGHT','Gate changed from B24 to A12 for SK102. Your airport route has been updated.',?)").run(now())}const affected=db.prepare("SELECT id,user_id FROM waitlist_entries WHERE flight_id=? AND status IN ('ACTIVE','PAYMENT_PENDING')").all(f.id)as any[];for(const w of affected)db.prepare('INSERT INTO waitlist_events(waitlist_id,user_id,flight_id,event_type,metadata,created_at) VALUES(?,?,?,?,?,?)').run(w.id,w.user_id,f.id,type==='delay'?'FLIGHT_DELAYED':'GATE_CHANGED',JSON.stringify(type==='delay'?{delayMinutes:35}:{from:'B24',to:'A12'}),now());r.json({ok:true})});
app.post('/api/demo/reset',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;if(q.body?.confirmed!==true)return r.status(428).json({error:'Explicit reset confirmation is required'});seed();r.json({ok:true})}); app.get('/api/notifications',(q,r)=>{const u=identity(q);if(!u)return r.status(401).json({error:'Authentication required'});const email=u.email;const expiring=db.prepare("SELECT n.id,o.promo_code,o.expires_at FROM offer_notifications n JOIN offers o ON o.id=n.offer_id WHERE n.user_id=? AND n.sent_at IS NULL AND datetime(o.expires_at)<=datetime('now','+1 day') AND datetime(o.expires_at)>datetime('now')").all(u.id)as any[];for(const x of expiring){db.prepare("INSERT INTO notifications(recipient,category,message,created_at) VALUES(?,'SYSTEM',?,?)").run(email,`Your saved ${x.promo_code} offer expires within 24 hours.`,now());db.prepare('UPDATE offer_notifications SET sent_at=? WHERE id=?').run(now(),x.id)}r.json(db.prepare("SELECT id,category,message,is_read,created_at FROM notifications WHERE recipient=? OR recipient='all' ORDER BY id DESC").all(email))});
app.get('/api/admin/stats',(q,r)=>{if(!requireRole(q,r,['AIRLINE_ADMIN','SYSTEM_ADMIN']))return;const one=(s:string)=>(db.prepare(s).get() as any).c; r.json({users:one('SELECT count(*) c FROM users'),flights:one('SELECT count(*) c FROM flights'),bookings:one("SELECT count(*) c FROM bookings WHERE status='CONFIRMED'"),cancelled:one("SELECT count(*) c FROM bookings WHERE status='CANCELLED'"),waitlist:one("SELECT count(*) c FROM waitlist_entries WHERE status IN ('ACTIVE','PAYMENT_PENDING')"),recovered:one("SELECT count(*) c FROM audit_logs WHERE action='SEAT_RECOVERY'"),revenue:(db.prepare("SELECT COALESCE(sum(total),0) c FROM bookings WHERE status='CONFIRMED'").get() as any).c})});
// ---- Production static hosting: serve the built frontend from this same server.
// Registered last, so it can never shadow an /api route. Only activates when a build exists.
const distDir=path.join(process.cwd(),'dist');
// In `npm run dev` Vite owns the UI on 5173; serving a stale dist/ from the API
// port as well would show outdated UI. So the API only serves the frontend when
// it is NOT in dev mode (or when explicitly forced).
const serveFrontend=process.env.ENABLE_DEV_SESSIONS!=='true'||process.env.SERVE_FRONTEND==='true';
if(serveFrontend&&fs.existsSync(path.join(distDir,'index.html'))){
  // Allow embedding in sandboxed iframes (opaque "null" origin) and any static
  // preview host. Without this the built module scripts are blocked by CORS and
  // the page renders blank. Applies to static assets only, never to /api.
  app.use((req,res,next)=>{ if(!req.path.startsWith('/api')) res.setHeader('Access-Control-Allow-Origin','*'); next(); });
  app.use(express.static(distDir,{index:false,maxAge:'1h'}));
  app.use((req,res,next)=>{
    if(req.method!=='GET'&&req.method!=='HEAD')return next();
    if(req.path.startsWith('/api'))return next();
    // Only fall back to the SPA shell for navigation-style requests. A missing
    // asset (e.g. /assets/old-hash.js) must 404, not return HTML with a 200 —
    // a browser would then report a confusing MIME error and CDNs could cache it.
    const ext=path.extname(req.path);
    if(ext&&ext!=='.html')return res.status(404).type('text/plain').send('Not found');
    res.sendFile(path.join(distDir,'index.html'));
  });
  console.log('Serving frontend build from',distDir);
}
const PORT=Number(process.env.PORT)||3001;
app.listen(PORT,'0.0.0.0',()=>console.log(`SkyBook API on ${PORT}`));
